<?php get_header(); ?><main class="content-area container"><?php while(have_posts()):the_post(); ?><div class="split"><div class="split-image"><?php if(has_post_thumbnail()) the_post_thumbnail('large'); ?></div><div><span class="eyebrow">Gói liệu trình</span><h1 class="page-title"><?php the_title(); ?></h1><?php $price=beaute_spa_price(get_the_ID()); $sale=beaute_spa_price(get_the_ID(),true); if($sale): ?><p class="price"><?php echo esc_html($sale); ?> <del class="muted"><?php echo esc_html($price); ?></del></p><?php elseif($price): ?><p class="price"><?php echo esc_html($price); ?></p><?php else: ?><p class="muted">Liên hệ để biết giá</p><?php endif; ?><?php $duration=get_post_meta(get_the_ID(),'_spa_duration',true); if($duration): ?><p>Thời lượng: <?php echo esc_html($duration); ?></p><?php endif; ?><a class="btn" href="<?php echo esc_url(add_query_arg('goi',get_the_ID(),home_url('/dat-lich'))); ?>">Đặt lịch gói này</a></div></div><article class="entry-content" style="margin:50px auto"><?php the_content(); ?></article><?php endwhile; ?></main><?php get_footer(); ?>
